#!/usr/bin/env bash
# One-time setup for a Codespace / Dev Container demo: config, database, demo content, build.
set -euo pipefail
cd "$(dirname "$0")/../ark-web"

if [ ! -f .env ]; then
  if [ -n "${CODESPACE_NAME:-}" ]; then
    site="https://${CODESPACE_NAME}-3000.${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN}"
  else
    site="http://localhost:3000"
  fi
  rand() { node -e "console.log(require('crypto').randomBytes($1).toString('base64url'))"; }
  cat > .env <<EOF
# Generated by .devcontainer/setup.sh for a demo. Not for production.
SITE_URL=$site
DATABASE_URL=postgresql://ark:ark@localhost:5432/ark?schema=public
AUTH_SECRET=$(rand 48)
ADMIN_EMAIL=admin@example.com
ADMIN_NAME=Demo Admin
ADMIN_PASSWORD=$(rand 12)
SMTP_HOST=
TRUSTED_PROXY_COUNT=1
EOF
  echo "Wrote ark-web/.env (SITE_URL=$site)"
fi

npm ci

# The database container may still be starting.
for i in $(seq 1 30); do
  if npx prisma migrate deploy; then break; fi
  [ "$i" = 30 ] && { echo "Database did not become ready" >&2; exit 1; }
  sleep 2
done

# Review data: a snapshot of the development database (.devcontainer/demo-data.sql) when present,
# otherwise generated sample content. Either way, the seed then adds the demo admin from .env.
DEMO_DATA="../.devcontainer/demo-data.sql"
if [ -f "$DEMO_DATA" ] && [ "$(node -e "const{PrismaClient}=require('@prisma/client');const d=new PrismaClient();d.event.count().then(n=>{console.log(n);return d.\$disconnect()})")" = "0" ]; then
  npx prisma db execute --file "$DEMO_DATA" --schema prisma/schema.prisma
  echo "Loaded review data from $DEMO_DATA"
  npm run db:seed
else
  npm run db:seed -- --demo
fi
npm run build
echo "Setup complete."
